//! The `.ttinsn` push-fusion experiment's T1 image
//! (`docs/plans/ttinsn-push-experiment.md`): the generic runner on T1, with two
//! hooks and nothing else changed.
//!
//! * A staged program that is one of the programs this image was built with
//!   (`ttinsn_programs.in`, generated by `probe_ttinsn_push`) may be pushed by
//!   fused `.ttinsn` words instead of read from L1 -- if the host asks for it.
//!   `MODE` in the scratch block says: 0 pushes every program the way the runner
//!   does, so a baseline runs *this binary*, same layout, same I-cache; 1 pushes
//!   a matching program fused from words built into the image; 2 **translates**
//!   the staged program into fused code in L1 at run time (`tt_firmware::ttinsn`),
//!   invalidates T1's instruction cache, and calls it; 3 runs the invalidation
//!   self-test and pushes nothing. Bit 8 of `MODE` times the translation with
//!   the core's own cycle counter (silicon only: ttsim has none), bit 9 skips the
//!   invalidation (ttsim has no instruction cache to invalidate), bit 10 skips the
//!   per-word opcode check, bit 11 leaves instruction gathering on (every image turns it
//!   off, as tt-metal's firmware does: `tt_firmware::disable_gathering`).
//! * After the coprocessor retires the program, a checksum of each 64-row band
//!   of `Dst` goes to the scratch block, so the host compares the whole of a
//!   result across the two modes rather than the sixteen rows the runner can dump.
//!
//! Built only with the `ttinsn-experiment` feature, and the one image whose
//! instruction-set gate admits `.ttinsn` words, and only in the `.ttinsn` section.
//! Linked at T1's default reset PC like `role_t1`.

#![no_std]
#![no_main]

use tt_firmware::corpus::{self, experiment};
use tt_firmware::ttinsn;
use tt_firmware::{l1_read32, l1_write32, publish};
use tt_isa::mailbox::MAILBOX_BASE;
use tt_isa::sfpu::dst32_address;
use tt_isa::tensix::{RiscvT1, Thread1};

/// The scratch block: free L1 inside the single-core mailbox's span, clear of
/// the role mailboxes, which sit at `mailbox::role::BASE` and up.
const SCRATCH: u64 = MAILBOX_BASE + 0x3500;
/// Host-written: 0 = the runner's own push, 1 = fused where a program matches.
const MODE: u64 = SCRATCH;
/// Written here: how many programs this run pushed fused (0 or 1).
const FUSED: u64 = SCRATCH + 4;
/// Written here, once started: a constant the host looks for, so a stale block
/// is not mistaken for a result.
const STAMP: u64 = SCRATCH + 8;
const STAMP_VALUE: u32 = 0x7717_0001;
/// Written here: four checksums, of `Dst` rows 0..64 (`A`), 64..128 (`B`),
/// 128..192 (an SFPU program's result) and 192..256, one word each.
const CHECKSUMS: u64 = SCRATCH + 16;
const BANDS: u32 = 4;
const BAND_ROWS: u32 = 64;
/// Written here by mode 2: words of fused code written, and the cycles spent
/// translating and invalidating (when asked).
const TRANSLATED: u64 = SCRATCH + 32;
const TRANSLATE_CYCLES: u64 = SCRATCH + 36;
/// Written here by mode 3: what the self-test's three calls returned.
const SELFTEST: u64 = SCRATCH + 40;

const MODE_BAKED: u32 = 1;
const MODE_TRANSLATE: u32 = 2;
const MODE_SELFTEST: u32 = 3;
const FLAG_TIME: u32 = 1 << 8;
const FLAG_NO_INVALIDATE: u32 = 1 << 9;
const FLAG_NO_OPCODE_CHECK: u32 = 1 << 10;
/// Leave instruction gathering (the hardware fusion of adjacent `.ttinsn` words)
/// on, as the core boots. Without it every image turns it off before anything is
/// pushed, as tt-metal's firmware does (`tt_firmware::disable_gathering`).
const FLAG_GATHERING_ON: u32 = 1 << 11;
/// Written here after every retired program: `cfg0` as the core reads it, so a
/// host can see whether gathering (`DisTriscCache`, bit 18) is off.
const CFG0_READBACK: u64 = SCRATCH + 52;

/// Where translated code goes: the last 16 KiB of L1, the program-cache region
/// no test of this experiment uses. (A real design would plan it through
/// `l1::Requirements`.)
const CODE_BUFFER: u64 = tt_isa::tensix::L1_SIZE - 0x4000;
const CODE_WORDS: usize = 0x4000 / 4;

include!("../ttinsn_programs.in");

/// Push the staged program by the means `MODE` names, returning whether it did.
///
/// # Safety
///
/// `code` and `code_len` are the runner's checked program.
unsafe fn try_push(code: u64, code_len: u32, loops: &[(u32, u32, u32)]) -> bool {
    // SAFETY: fixed aligned scratch word.
    let word = unsafe { l1_read32(MODE) };
    match word & 0xff {
        MODE_BAKED => baked(code, code_len, loops.len() as u32),
        MODE_TRANSLATE => translated(code, code_len, loops, word),
        MODE_SELFTEST => {
            selftest();
            true
        }
        _ => false,
    }
}

/// Push the matching built-in program, if one matches.
///
/// A match is the stored length and block-repeat count plus the first and last
/// four words: cheap, because this runs between the runner's `START` and `PUSHED`
/// events and must not be what is measured. The host then checks the whole
/// program by comparing every row of its result against the same binary's own
/// push.
unsafe fn baked(code: u64, code_len: u32, loops: u32) -> bool {
    for p in PROGRAMS.iter() {
        if p.code_len != code_len || p.loops != loops || code_len == 0 {
            continue;
        }
        let at = |k: usize| unsafe { l1_read32(code + 4 * k as u64) };
        let n = code_len as usize;
        // The first and last (up to) four words.
        let same = (0..p.head.len()).all(|k| at(k) == p.head[k])
            && (0..p.tail.len()).all(|k| at(n - p.tail.len() + k) == p.tail[k]);
        if same {
            // SAFETY: the program's generated code, built from the same
            // instructions the host staged; it only stores to `INSTRN_BUF_BASE`
            // and clobbers `t0` and `t1`.
            unsafe { (p.run)() };
            // SAFETY: a fixed aligned scratch word.
            unsafe { l1_write32(FUSED, 1) };
            return true;
        }
    }
    false
}

/// Translate the staged program into fused code, invalidate T1's instruction
/// cache so the new code is what is fetched, and call it.
unsafe fn translated(code: u64, code_len: u32, loops: &[(u32, u32, u32)], word: u32) -> bool {
    let timed = word & FLAG_TIME != 0;
    // SAFETY: a CSR read; only when the host says this is silicon.
    let start = if timed { tt_firmware::cycles() } else { 0 };
    // SAFETY: the runner's checked program, and a buffer this image owns.
    let Some(n) = (unsafe {
        ttinsn::translate(
            code,
            code_len,
            loops,
            (word & FLAG_NO_OPCODE_CHECK == 0).then_some(&OPCODES),
            CODE_BUFFER,
            CODE_WORDS,
        )
    }) else {
        return false;
    };
    if word & FLAG_NO_INVALIDATE == 0 {
        // SAFETY: the last word just written; mask 4 is this core (T1).
        unsafe { ttinsn::invalidate_icache(CODE_BUFFER + 4 * (n as u64 - 1), 4) };
    } else {
        tt_firmware::publish();
    }
    // SAFETY: a fixed aligned scratch word.
    unsafe {
        l1_write32(TRANSLATED, n as u32);
        if timed {
            l1_write32(TRANSLATE_CYCLES, tt_firmware::cycles().wrapping_sub(start));
        }
    }
    // SAFETY: valid code ending in a return, translated above; its cache lines
    // were invalidated after it was written.
    unsafe { ttinsn::call(CODE_BUFFER) };
    // SAFETY: a fixed aligned scratch word.
    unsafe { l1_write32(FUSED, 2) };
    true
}

/// The invalidation self-test, on code that pushes nothing: `a0 = 1; ret`, called
/// (so its lines are cached); rewritten to `a0 = 2` and called *without*
/// invalidating (a stale cache returns 1); then invalidated and called (must
/// return 2). The three results go to the scratch block.
unsafe fn selftest() {
    // SAFETY: this image owns the buffer; the code is `a0 = value; ret`.
    unsafe {
        ttinsn::write_return_value(CODE_BUFFER, 1);
        ttinsn::invalidate_icache(CODE_BUFFER + 4, 4);
        let first = ttinsn::call(CODE_BUFFER);
        ttinsn::write_return_value(CODE_BUFFER, 2);
        tt_firmware::publish();
        let stale = ttinsn::call(CODE_BUFFER);
        ttinsn::invalidate_icache(CODE_BUFFER + 4, 4);
        let fresh = ttinsn::call(CODE_BUFFER);
        l1_write32(SELFTEST, first);
        l1_write32(SELFTEST + 4, stale);
        l1_write32(SELFTEST + 8, fresh);
    }
}

/// An FNV-1a checksum of each band of `Dst` rows, in row-major order. (A first
/// version xor-rotated, and cancelled to zero on the repeated four-row pattern the
/// prelude writes: a checksum that cannot tell results apart validates nothing.)
fn after_retire() {
    for band in 0..BANDS {
        let mut sum = 0x811c_9dc5u32;
        for row in band * BAND_ROWS..(band + 1) * BAND_ROWS {
            for column in 0..16 {
                // SAFETY: the coprocessor has retired the program, and the runner
                // set a 32-bit `Dst` shape.
                let v = unsafe { tt_firmware::tensix::read_dst32(dst32_address(row, column)) };
                sum = (sum ^ v).wrapping_mul(0x0100_0193);
            }
        }
        // SAFETY: fixed aligned scratch words.
        unsafe { l1_write32(CHECKSUMS + 4 * band as u64, sum) };
    }
    let cfg0: u32;
    // SAFETY: reads the custom CSR `cfg0`; no side effects.
    unsafe { core::arch::asm!("csrr {0}, 0x7c0", out(reg) cfg0, options(nomem, nostack)) };
    // SAFETY: a fixed aligned scratch word.
    unsafe { l1_write32(CFG0_READBACK, cfg0) };
    publish();
}

/// The inverse of `tt_firmware::disable_gathering`, for the measurements that
/// compare against it: the same sequence with `DisTriscCache` cleared.
fn enable_gathering() {
    // SAFETY: the custom CSR `cfg0`, as `tt_firmware::disable_gathering`.
    unsafe {
        core::arch::asm!(
            "li   t1, 0x2",
            "csrrs zero, 0x7c0, t1",
            "li   t1, 0x1",
            "slli t1, t1, 18",
            "fence",
            "csrrc zero, 0x7c0, t1",
            "li   t1, 0x2",
            "csrrc zero, 0x7c0, t1",
            "fence",
            out("t1") _,
        );
    }
}

#[no_mangle]
pub extern "Rust" fn firmware_main() -> ! {
    // SAFETY: fixed aligned scratch words; the hooks are set before the runner
    // starts and never again.
    unsafe {
        l1_write32(FUSED, 0);
        for band in 0..BANDS {
            l1_write32(CHECKSUMS + 4 * band as u64, 0);
        }
        l1_write32(STAMP, STAMP_VALUE);
        experiment::TRY_PUSH = Some(try_push);
        experiment::AFTER_RETIRE = Some(after_retire);
    }
    publish();
    // SAFETY: a fixed aligned scratch word.
    if unsafe { l1_read32(MODE) } & FLAG_GATHERING_ON != 0 {
        // Cleared explicitly, not just left alone: `cfg0` can keep a previous
        // run's bits across the core's reset (ttsim does), and a measurement
        // "with gathering on" must not depend on what ran before it.
        enable_gathering();
        unsafe { experiment::KEEP_GATHERING = true };
    }
    corpus::run_role::<RiscvT1, Thread1>()
}
